parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "resumen": {
      "type": "string",
      "description": "Resumen del problema en una frase"
    },
    "urgencia": {
      "type": "string",
      "enum": ["Alta", "Media", "Baja"],
      "description": "Nivel de urgencia del ticket"
    },
    "departamento": {
      "type": "string",
      "enum": ["Sistemas", "Desarrollo", "Facturacion"],
      "description": "Departamento responsable de resolverlo"
    },
    "justificacion": {
      "type": "string",
      "description": "Motivo de la urgencia y del departamento asignados"
    },
    "palabras_clave": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Términos clave detectados en la queja"
    }
  },
  "required": ["resumen", "urgencia", "departamento", "justificacion", "palabras_clave"],
  "additionalProperties": false
}
